     1→type RateLimitConfig = {
     2→  maxRequests: number;
     3→  windowMs: number;
     4→  retryAfterMs?: number;
     5→};
     6→
     7→type RateLimitState = {
     8→  requests: number;
     9→  windowStart: number;
    10→  nextResetTime: number;
    11→};
    12→
    13→export class RateLimiter {
    14→  private readonly config: RateLimitConfig;
    15→  private state: RateLimitState;
    16→
    17→  constructor(config: RateLimitConfig) {
    18→    this.config = {
    19→      retryAfterMs: 60000, // 1 minute default
    20→      ...config,
    21→    };
    22→    this.state = {
    23→      requests: 0,
    24→      windowStart: Date.now(),
    25→      nextResetTime: Date.now() + this.config.windowMs,
    26→    };
    27→  }
    28→
    29→  async checkLimit(): Promise<{ allowed: boolean; retryAfter?: number }> {
    30→    const now = Date.now();
    31→
    32→    // Reset window if expired
    33→    if (now >= this.state.nextResetTime) {
    34→      this.state = {
    35→        requests: 0,
    36→        windowStart: now,
    37→        nextResetTime: now + this.config.windowMs,
    38→      };
    39→    }
    40→
    41→    // Check if within limit
    42→    if (this.state.requests < this.config.maxRequests) {
    43→      this.state.requests++;
    44→      return { allowed: true };
    45→    }
    46→
    47→    // Calculate retry after
    48→    const retryAfter = Math.ceil((this.state.nextResetTime - now) / 1000);
    49→
    50→    return { allowed: false, retryAfter };
    51→  }
    52→
    53→  getStats() {
    54→    return {
    55→      requests: this.state.requests,
    56→      maxRequests: this.config.maxRequests,
    57→      windowStart: this.state.windowStart,
    58→      nextReset: this.state.nextResetTime,
    59→      remainingRequests: Math.max(
    60→        0,
    61→        this.config.maxRequests - this.state.requests,
    62→      ),
    63→    };
    64→  }
    65→}
