     1→type CacheEntry<T> = {
     2→  data: T;
     3→  timestamp: number;
     4→  ttl: number;
     5→};
     6→
     7→export class MemoryCache {
     8→  private readonly cache = new Map<string, CacheEntry<unknown>>();
     9→  private readonly defaultTtl: number;
    10→
    11→  constructor(defaultTtlMs = 300000) {
    12→    // 5 minutes default
    13→    this.defaultTtl = defaultTtlMs;
    14→  }
    15→
    16→  set<T>(key: string, data: T, ttlMs?: number): void {
    17→    const entry: CacheEntry<T> = {
    18→      data,
    19→      timestamp: Date.now(),
    20→      ttl: ttlMs ?? this.defaultTtl,
    21→    };
    22→    this.cache.set(key, entry);
    23→  }
    24→
    25→  get<T>(key: string): T | null {
    26→    const entry = this.cache.get(key);
    27→    if (!entry) {
    28→      return null;
    29→    }
    30→
    31→    const now = Date.now();
    32→    const isExpired = now - entry.timestamp > entry.ttl;
    33→
    34→    if (isExpired) {
    35→      this.cache.delete(key);
    36→      return null;
    37→    }
    38→
    39→    return entry.data as T;
    40→  }
    41→
    42→  has(key: string): boolean {
    43→    const entry = this.cache.get(key);
    44→    if (!entry) {
    45→      return false;
    46→    }
    47→
    48→    const now = Date.now();
    49→    const isExpired = now - entry.timestamp > entry.ttl;
    50→
    51→    if (isExpired) {
    52→      this.cache.delete(key);
    53→      return false;
    54→    }
    55→
    56→    return true;
    57→  }
    58→
    59→  delete(key: string): boolean {
    60→    return this.cache.delete(key);
    61→  }
    62→
    63→  clear(): void {
    64→    this.cache.clear();
    65→  }
    66→
    67→  size(): number {
    68→    return this.cache.size;
    69→  }
    70→
    71→  cleanup(): number {
    72→    const now = Date.now();
    73→    let removedCount = 0;
    74→
    75→    for (const [key, entry] of this.cache.entries()) {
    76→      const isExpired = now - entry.timestamp > entry.ttl;
    77→      if (isExpired) {
    78→        this.cache.delete(key);
    79→        removedCount++;
    80→      }
    81→    }
    82→
    83→    return removedCount;
    84→  }
    85→
    86→  generateKey(prefix: string, params: Record<string, unknown>): string {
    87→    const sortedParams = Object.keys(params)
    88→      .sort()
    89→      .map((key) => `${key}=${JSON.stringify(params[key])}`)
    90→      .join("&");
    91→    return `${prefix}:${sortedParams}`;
    92→  }
    93→}
