     1→import { logger } from "@/lib/logger";
     2→import type { DVFProperty, DVFSearchCriteria } from "./types";
     3→import {
     4→  DVFAPIError,
     5→  DVFValidationError,
     6→  DVFDataNotFoundError,
     7→  DVFSearchCriteriaSchema,
     8→} from "./types";
     9→
    10→type DVFClientConfig = {
    11→  baseUrl?: string;
    12→  timeout?: number;
    13→  maxRetries?: number;
    14→};
    15→
    16→/**
    17→ * Client pour l'API DVF (Demandes de Valeurs Foncières)
    18→ * Utilise l'API Carto basée sur les données data.gouv.fr
    19→ */
    20→export class DVFClient {
    21→  private readonly baseUrl: string;
    22→  private readonly timeout: number;
    23→  private readonly maxRetries: number;
    24→
    25→  constructor(config: DVFClientConfig = {}) {
    26→    // API publique basée sur les données DVF
    27→    this.baseUrl =
    28→      config.baseUrl ?? "https://apidf-preprod.lab.sspcloud.fr/dvf";
    29→    this.timeout = config.timeout ?? 30000; // 30 secondes
    30→    this.maxRetries = config.maxRetries ?? 3;
    31→  }
    32→
    33→  /**
    34→   * Recherche les transactions DVF selon des critères géographiques et temporels
    35→   */
    36→  async searchTransactions(
    37→    criteria: DVFSearchCriteria,
    38→  ): Promise<DVFProperty[]> {
    39→    // Validation des critères
    40→    const validatedCriteria = DVFSearchCriteriaSchema.parse(criteria);
    41→
    42→    logger.debug("🏠 [DVF] Recherche transactions", {
    43→      coordinates: validatedCriteria.coordinates,
    44→      radiusKm: validatedCriteria.radiusKm,
    45→      period: `${validatedCriteria.fromDate} - ${validatedCriteria.toDate}`,
    46→    });
    47→
    48→    try {
    49→      const properties = await this.executeRequest(validatedCriteria);
    50→
    51→      logger.debug(`📊 [DVF] Trouvé ${properties.length} transactions`, {
    52→        avgPricePerM2:
    53→          properties.length > 0
    54→            ? properties.reduce(
    55→                (sum, p) => sum + (p.surface ? p.propertyValue / p.surface : 0),
    56→                0,
    57→              ) / properties.filter((p) => p.surface).length
    58→            : 0,
    59→      });
    60→
    61→      return properties;
    62→    } catch (error) {
    63→      if (error instanceof DVFAPIError || error instanceof DVFValidationError) {
    64→        throw error;
    65→      }
    66→
    67→      logger.error("❌ [DVF] Erreur lors de la recherche", { error });
    68→      throw new DVFAPIError(
    69→        "Erreur lors de la récupération des données DVF",
    70→        500,
    71→      );
    72→    }
    73→  }
    74→
    75→  /**
    76→   * Recherche les transactions dans un rayon autour d'un point
    77→   * avec des filtres automatiques pour des biens similaires
    78→   */
    79→  async searchSimilarProperties(
    80→    coordinates: { lat: number; lng: number },
    81→    propertyType: string,
    82→    surface: number,
    83→    radiusKm = 1,
    84→    periodMonths = 24,
    85→  ): Promise<DVFProperty[]> {
    86→    const fromDate = new Date();
    87→    fromDate.setMonth(fromDate.getMonth() - periodMonths);
    88→
    89→    const criteria: DVFSearchCriteria = {
    90→      coordinates,
    91→      radiusKm,
    92→      fromDate: fromDate.toISOString().split("T")[0],
    93→      toDate: new Date().toISOString().split("T")[0],
    94→      propertyTypes: [this.normalizePropertyType(propertyType)],
    95→      // Surface +/- 30%
    96→      minSurface: Math.floor(surface * 0.7),
    97→      maxSurface: Math.ceil(surface * 1.3),
    98→      limit: 100,
    99→    };
   100→
   101→    return this.searchTransactions(criteria);
   102→  }
   103→
   104→  /**
   105→   * Méthodes utilitaires pour les développeurs
   106→   */
   107→  getApiUrl(): string {
   108→    return this.baseUrl;
   109→  }
   110→
   111→  getTimeout(): number {
   112→    return this.timeout;
   113→  }
   114→
   115→  private async executeRequest(
   116→    criteria: DVFSearchCriteria,
   117→    attempt = 1,
   118→  ): Promise<DVFProperty[]> {
   119→    const controller = new AbortController();
   120→    const timeoutId = setTimeout(() => controller.abort(), this.timeout);
   121→
   122→    try {
   123→      // Construction de l'URL avec les paramètres de recherche géographique
   124→      const url = this.buildSearchUrl(criteria);
   125→
   126→      logger.debug(
   127→        `🔍 [DVF] Requête API (tentative ${attempt}/${this.maxRetries}):`,
   128→        url,
   129→      );
   130→
   131→      const response = await fetch(url, {
   132→        method: "GET",
   133→        headers: {
   134→          Accept: "application/json",
   135→          "User-Agent": "ChooseWisely/1.0 (contact@choosewisely.fr)",
   136→        },
   137→        signal: controller.signal,
   138→      });
   139→
   140→      clearTimeout(timeoutId);
   141→
   142→      if (!response.ok) {
   143→        if (response.status === 404) {
   144→          throw new DVFDataNotFoundError();
   145→        }
   146→
   147→        const errorText = await response.text().catch(() => "Erreur inconnue");
   148→        throw new DVFAPIError(
   149→          `Erreur API DVF: ${response.status} - ${errorText}`,
   150→          response.status,
   151→        );
   152→      }
   153→
   154→      const data = await response.json();
   155→
   156→      return this.transformApiResponse(data);
   157→    } catch (error) {
   158→      clearTimeout(timeoutId);
   159→
   160→      if (
   161→        error instanceof DVFAPIError ||
   162→        error instanceof DVFDataNotFoundError
   163→      ) {
   164→        throw error;
   165→      }
   166→
   167→      // Retry logic
   168→      if (attempt < this.maxRetries) {
   169→        const delay = Math.min(1000 * Math.pow(2, attempt - 1), 5000);
   170→        logger.debug(`⏳ [DVF] Retry dans ${delay}ms`);
   171→
   172→        await new Promise((resolve) => setTimeout(resolve, delay));
   173→        return this.executeRequest(criteria, attempt + 1);
   174→      }
   175→
   176→      if (error instanceof Error && error.name === "AbortError") {
   177→        throw new DVFAPIError("Timeout lors de la requête DVF", 408);
   178→      }
   179→
   180→      throw new DVFAPIError(
   181→        "Erreur réseau lors de l'accès aux données DVF",
   182→        500,
   183→      );
   184→    }
   185→  }
   186→
   187→  private buildSearchUrl(criteria: DVFSearchCriteria): string {
   188→    const params = new URLSearchParams();
   189→
   190→    // Recherche géographique par coordonnées et rayon
   191→    params.append("lat", criteria.coordinates.lat.toString());
   192→    params.append("lon", criteria.coordinates.lng.toString());
   193→    params.append("dist", (criteria.radiusKm * 1000).toString()); // API attend des mètres
   194→
   195→    // Filtres temporels
   196→    if (criteria.fromDate) {
   197→      params.append("date_debut", criteria.fromDate);
   198→    }
   199→    if (criteria.toDate) {
   200→      params.append("date_fin", criteria.toDate);
   201→    }
   202→
   203→    // Filtres de surface
   204→    if (criteria.minSurface) {
   205→      params.append("surface_min", criteria.minSurface.toString());
   206→    }
   207→    if (criteria.maxSurface) {
   208→      params.append("surface_max", criteria.maxSurface.toString());
   209→    }
   210→
   211→    // Type de bien
   212→    if (criteria.propertyTypes && criteria.propertyTypes.length > 0) {
   213→      params.append("type_local", criteria.propertyTypes.join(","));
   214→    }
   215→
   216→    // Limite
   217→    if (criteria.limit) {
   218→      params.append("limit", criteria.limit.toString());
   219→    }
   220→
   221→    return `${this.baseUrl}/mutations?${params.toString()}`;
   222→  }
   223→
   224→  private transformApiResponse(apiData: unknown): DVFProperty[] {
   225→    if (!apiData || !Array.isArray(apiData)) {
   226→      logger.warn("⚠️ [DVF] Format de réponse API inattendu", { apiData });
   227→      return [];
   228→    }
   229→
   230→    return apiData
   231→      .map((item: unknown, index: number) => {
   232→        try {
   233→          return this.transformSingleProperty(
   234→            item as Record<string, unknown>,
   235→            index,
   236→          );
   237→        } catch (error) {
   238→          logger.warn(
   239→            `⚠️ [DVF] Erreur transformation propriété index ${index}:`,
   240→            error,
   241→          );
   242→          return null;
   243→        }
   244→      })
   245→      .filter((property): property is DVFProperty => property !== null);
   246→  }
   247→
   248→  private transformSingleProperty(
   249→    apiItem: Record<string, unknown>,
   250→    index: number,
   251→  ): DVFProperty {
   252→    // Adaptation selon le format réel de l'API DVF
   253→    // Les noms de champs peuvent varier selon l'API utilisée
   254→    const property: DVFProperty = {
   255→      id: apiItem.id_mutation
   256→        ? String(apiItem.id_mutation)
   257→        : `dvf_${Date.now()}_${index}`,
   258→      mutationDate: String(apiItem.date_mutation ?? apiItem.date ?? ""),
   259→      dispositionNature: String(apiItem.nature_mutation ?? "Vente"),
   260→      propertyValue: parseFloat(
   261→        String(apiItem.valeur_fonciere ?? apiItem.prix ?? 0),
   262→      ),
   263→      address: this.buildAddress(apiItem),
   264→      postalCode: String(apiItem.code_postal ?? ""),
   265→      city: String(apiItem.commune ?? apiItem.nom_commune ?? ""),
   266→      department: String(apiItem.code_departement ?? ""),
   267→      surface: apiItem.surface_reelle_bati
   268→        ? parseFloat(apiItem.surface_reelle_bati as string)
   269→        : null,
   270→      landSurface: apiItem.surface_terrain
   271→        ? parseFloat(apiItem.surface_terrain as string)
   272→        : null,
   273→      rooms: apiItem.nombre_pieces_principales
   274→        ? parseInt(apiItem.nombre_pieces_principales as string)
   275→        : null,
   276→      propertyType: String(
   277→        apiItem.type_local ?? apiItem.nature_culture ?? "Appartement",
   278→      ),
   279→    };
   280→
   281→    // Coordonnées si disponibles
   282→    if (apiItem.latitude && apiItem.longitude) {
   283→      property.coordinates = {
   284→        lat: parseFloat(String(apiItem.latitude)),
   285→        lng: parseFloat(String(apiItem.longitude)),
   286→      };
   287→    }
   288→
   289→    return property;
   290→  }
   291→
   292→  private buildAddress(apiItem: Record<string, unknown>): string {
   293→    const parts = [
   294→      apiItem.numero_voie,
   295→      apiItem.type_voie,
   296→      apiItem.voie,
   297→      apiItem.commune,
   298→    ].filter(Boolean);
   299→
   300→    return parts.join(" ") || "Adresse non spécifiée";
   301→  }
   302→
   303→  private normalizePropertyType(type: string): string {
   304→    const typeMap: Record<string, string> = {
   305→      flat: "Appartement",
   306→      apartment: "Appartement",
   307→      house: "Maison",
   308→      land: "Terrain",
   309→      office: "Bureau",
   310→      shop: "Commerce",
   311→      warehouse: "Entrepôt",
   312→      building: "Immeuble",
   313→    };
   314→
   315→    return typeMap[type.toLowerCase()] ?? "Appartement";
   316→  }
   317→}
