    58→  /**
    59→   * Analyse complète d'un bien par rapport au marché local DVF
    60→   */
    61→  async analyzeProperty(property: PropertyToAnalyze): Promise<DVFAnalysis> {
    62→    logger.debug("🔍 [DVFAnalyzer] Début analyse DVF", {
    63→      price: property.price,
    64→      surface: property.surface,
    65→      coordinates: property.coordinates,
    66→    });
    67→
    68→    if (property.surface <= 0) {
    69→      throw new DVFValidationError(
    70→        "Coordonnées et surface valides requis pour l'analyse DVF",
    71→      );
    72→    }
    73→
    74→    try {
    75→      // 1. Recherche des biens comparables
    76→      const comparables = await this.findComparableProperties(property);
    77→
    78→      if (comparables.length === 0) {
    79→        throw new DVFDataNotFoundError(
    80→          "Aucune transaction comparable trouvée dans la zone",
    81→        );
    82→      }
    83→
    84→      // 2. Calcul des métriques de marché
    85→      const marketMetrics = this.calculateMarketMetrics(comparables);
    86→
    87→      // 3. Analyse de sur-évaluation
    88→      const propertyPricePerM2 = property.price / property.surface;
    89→      const overpricingPercent =
    90→        ((propertyPricePerM2 - marketMetrics.median) / marketMetrics.median) *
    91→        100;
    92→      const overpricingAmount =
    93→        (propertyPricePerM2 - marketMetrics.median) * property.surface;
    94→
    95→      // 4. Analyse temporelle (évolution des prix)
    96→      const priceEvolution = await this.calculatePriceEvolution(
    97→        property,
    98→        comparables,
    99→      );
   100→
   101→      // 5. Niveau de confiance
   102→      const confidence = this.calculateConfidenceLevel(
   103→        comparables.length,
   104→        marketMetrics.standardDeviation,
   105→        propertyPricePerM2,
   106→      );
   107→
   108→      const analysis: DVFAnalysis = {
   109→        // Prix de référence du marché
   110→        medianPricePerM2: marketMetrics.median,
   111→        averagePricePerM2: marketMetrics.average,
   112→        minPricePerM2: marketMetrics.min,
   113→        maxPricePerM2: marketMetrics.max,
   114→
   115→        // Analyse du bien
   116→        propertyPricePerM2,
   117→        overpricingPercent: Math.round(overpricingPercent * 100) / 100,
   118→        overpricingAmount: Math.round(overpricingAmount),
   119→
   120→        // Contexte
   121→        comparableCount: comparables.length,
   122→        radiusKm: 1, // TODO: dynamique selon densité
   123→        periodMonths: 24,
   124→
   125→        // Évolution
   126→        priceEvolution,
   127→
   128→        // Confiance
   129→        confidenceLevel: confidence.level,
   130→        confidenceReason: confidence.reason,
   131→
   132→        // Métadonnées
   133→        lastUpdated: new Date().toISOString(),
   134→        dataSource: "DVF - data.gouv.fr",
   135→      };
   136→
   137→      logger.debug("✅ [DVFAnalyzer] Analyse terminée", {
   138→        overpricingPercent: analysis.overpricingPercent,
   139→        comparableCount: analysis.comparableCount,
   140→        confidenceLevel: analysis.confidenceLevel,
   141→      });
   142→
   143→      return analysis;
   144→    } catch (error) {
   145→      if (
   146→        error instanceof DVFDataNotFoundError ||
   147→        error instanceof DVFValidationError
   148→      ) {
   149→        throw error;
   150→      }
   151→
   152→      logger.error("❌ [DVFAnalyzer] Erreur lors de l'analyse:", error);
