   156→
   157→  /**
   158→   * Trouve les biens comparables autour du bien analysé
   159→   */
   160→  private async findComparableProperties(
   161→    property: PropertyToAnalyze,
   162→  ): Promise<DVFProperty[]> {
   163→    const radiusOptions = [0.5, 1, 2, 5]; // Rayons à essayer (km)
   164→    const minComparables = 5;
   165→
   166→    // Essayer chaque rayon séquentiellement jusqu'à trouver assez de comparables
   167→    for (const radiusKm of radiusOptions) {
   168→      logger.debug(
   169→        `🎯 [DVFAnalyzer] Recherche comparables rayon ${radiusKm}km`,
   170→      );
   171→
   172→      // Cette approche séquentielle est nécessaire car on veut s'arrêter
   173→      // dès qu'on a assez de comparables avec le plus petit rayon possible
   174→      // eslint-disable-next-line no-await-in-loop
   175→      const comparables = await this.dvfClient.searchSimilarProperties(
   176→        property.coordinates,
   177→        property.category,
   178→        property.surface,
   179→        radiusKm,
   180→        24, // 24 mois
   181→      );
   182→
   183→      // Filtrer pour garder les plus pertinents
   184→      const filteredComparables = this.filterRelevantComparables(
   185→        comparables,
   186→        property,
   187→      );
   188→
   189→      if (filteredComparables.length >= minComparables) {
   190→        logger.debug(
   191→          `✅ [DVFAnalyzer] Trouvé ${filteredComparables.length} comparables pertinents`,
   192→        );
   193→        return filteredComparables;
   194→      }
   195→    }
   196→
   197→    // Si pas assez de comparables même avec le plus grand rayon
   198→    logger.warn("⚠️ [DVFAnalyzer] Peu de comparables trouvés");
   199→    return [];
   200→  }
   201→
   202→  /**
   203→   * Filtre les biens comparables pour garder les plus pertinents
   204→   */
   205→  private filterRelevantComparables(
   206→    comparables: DVFProperty[],
   207→    property: PropertyToAnalyze,
   208→  ): DVFProperty[] {
   209→    return comparables
   210→      .filter((comp) => {
   211→        // Filtre de base : surface et prix cohérents
   212→        if (!comp.surface || comp.surface <= 0) return false;
   213→        if (!comp.propertyValue || comp.propertyValue <= 0) return false;
   214→
   215→        // Prix/m² cohérent (pas d'outliers extrêmes)
   216→        const pricePerM2 = comp.propertyValue / comp.surface;
   217→        const propertyPricePerM2 = property.price / property.surface;
   218→        const ratio = pricePerM2 / propertyPricePerM2;
   219→
   220→        // Garde les biens entre 0.3x et 3x le prix/m² du bien analysé
   221→        return ratio >= 0.3 && ratio <= 3;
   222→      })
   223→      .sort((a, b) => {
   224→        // Trie par pertinence : surface similaire d'abord
   225→        const surfaceDiffA = Math.abs((a.surface ?? 0) - property.surface);
   226→        const surfaceDiffB = Math.abs((b.surface ?? 0) - property.surface);
   227→        return surfaceDiffA - surfaceDiffB;
   228→      })
   229→      .slice(0, 100); // Limite à 100 comparables max
   230→  }
   231→
   232→  /**
   233→   * Calcule les métriques du marché à partir des comparables
   234→   */
   235→  private calculateMarketMetrics(comparables: DVFProperty[]) {
   236→    const pricesPerM2 = comparables
   237→      .filter((comp) => comp.surface && comp.surface > 0)
   238→      .map((comp) => comp.propertyValue / (comp.surface as number))
   239→      .sort((a, b) => a - b);
   240→
   241→    if (pricesPerM2.length === 0) {
   242→      throw new DVFDataNotFoundError("Aucune donnée de prix/m² valide trouvée");
   243→    }
   244→
   245→    const median = this.calculateMedian(pricesPerM2);
   246→    const average =
   247→      pricesPerM2.reduce((sum, price) => sum + price, 0) / pricesPerM2.length;
   248→    const min = pricesPerM2[0];
   249→    const max = pricesPerM2[pricesPerM2.length - 1];
   250→
   251→    // Écart-type pour évaluer la dispersion
   252→    const variance =
   253→      pricesPerM2.reduce(
   254→        (sum, price) => sum + Math.pow(price - average, 2),
   255→        0,
   256→      ) / pricesPerM2.length;
   257→    const standardDeviation = Math.sqrt(variance);
   258→
   259→    return {
   260→      median: Math.round(median),
   261→      average: Math.round(average),
   262→      min: Math.round(min),
   263→      max: Math.round(max),
   264→      standardDeviation: Math.round(standardDeviation),
   265→    };
   266→  }
   267→
   268→  /**
   269→   * Calcule l'évolution des prix sur différentes périodes
   270→   */
   271→  private async calculatePriceEvolution(
   272→    property: PropertyToAnalyze,
   273→    recentComparables: DVFProperty[],
   274→  ): Promise<DVFAnalysis["priceEvolution"]> {
   275→    try {
   276→      // Comparables des 6 derniers mois
   277→      const sixMonthsAgo = new Date();
   278→      sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
   279→
   280→      const recentComparablesFiltered = recentComparables.filter((comp) => {
   281→        const mutationDate = new Date(comp.mutationDate);
   282→        return mutationDate >= sixMonthsAgo;
   283→      });
   284→
   285→      if (recentComparablesFiltered.length < 3) {
   286→        return undefined; // Pas assez de données récentes
   287→      }
   288→
   289→      const recent6mMetrics = this.calculateMarketMetrics(
   290→        recentComparablesFiltered,
   291→      );
   292→      const recent12mMetrics = this.calculateMarketMetrics(recentComparables);
   293→
   294→      const evolutionPercent =
   295→        ((recent6mMetrics.median - recent12mMetrics.median) /
   296→          recent12mMetrics.median) *
   297→        100;
   298→
   299→      return {
   300→        last6Months: recent6mMetrics.median,
   301→        last12Months: recent12mMetrics.median,
   302→        evolutionPercent: Math.round(evolutionPercent * 100) / 100,
   303→      };
   304→    } catch (error) {
   305→      logger.warn(
   306→        "⚠️ [DVFAnalyzer] Impossible de calculer l'évolution des prix:",
   307→        error,
   308→      );
   309→      return undefined;
   310→    }
   311→  }
   312→
   313→  /**
   314→   * Calcule le niveau de confiance de l'analyse
   315→   */
   316→  private calculateConfidenceLevel(
   317→    comparableCount: number,
   318→    standardDeviation: number,
   319→    propertyPricePerM2: number,
   320→  ): { level: DVFAnalysis["confidenceLevel"]; reason: string } {
   321→    // Confiance basée sur le nombre de comparables
   322→    if (comparableCount >= 20) {
   323→      const coefficientVariation = standardDeviation / propertyPricePerM2;
   324→
   325→      if (coefficientVariation < 0.2) {
   326→        return {
   327→          level: "high",
   328→          reason: `${comparableCount} transactions similaires avec prix cohérents`,
   329→        };
   330→      } else {
   331→        return {
   332→          level: "medium",
   333→          reason: `${comparableCount} transactions trouvées mais prix dispersés`,
   334→        };
   335→      }
   336→    } else if (comparableCount >= 10) {
   337→      return {
   338→        level: "medium",
   339→        reason: `${comparableCount} transactions similaires trouvées`,
   340→      };
   341→    } else {
   342→      return {
   343→        level: "low",
   344→        reason: `Seulement ${comparableCount} transactions comparables`,
   345→      };
   346→    }
   347→  }
   348→
   349→  /**
   350→   * Calcule la médiane d'un tableau de nombres triés
   351→   */
   352→  private calculateMedian(sortedNumbers: number[]): number {
   353→    const length = sortedNumbers.length;
   354→    const middle = Math.floor(length / 2);
   355→
   356→    if (length % 2 === 0) {
   357→      return (sortedNumbers[middle - 1] + sortedNumbers[middle]) / 2;
   358→    } else {
   359→      return sortedNumbers[middle];
   360→    }
   361→  }
   362→}
