     8→class MemoryDVFCache {
     9→  private readonly cache = new Map<string, { data: unknown; expiry: number }>();
    10→  private readonly defaultTtl: number;
    11→
    12→  constructor(defaultTtlMs = 6 * 60 * 60 * 1000) {
    13→    // 6 heures par défaut
    14→    this.defaultTtl = defaultTtlMs;
    15→  }
    16→
    17→  set<T>(key: string, data: T, ttlMs?: number): void {
    18→    const expiry = Date.now() + (ttlMs ?? this.defaultTtl);
    19→    this.cache.set(key, { data, expiry });
    20→
    21→    logger.debug(
    22→      `💾 [DVF Cache] Stored key: ${key} (TTL: ${Math.round((ttlMs ?? this.defaultTtl) / 1000)}s)`,
    23→    );
    24→  }
    25→
    26→  get<T>(key: string): T | null {
    27→    const entry = this.cache.get(key);
    28→
    29→    if (!entry) {
    30→      return null;
    31→    }
    32→
    33→    if (Date.now() > entry.expiry) {
    34→      this.cache.delete(key);
    35→      logger.debug(`🗑️ [DVF Cache] Expired key removed: ${key}`);
    36→      return null;
    37→    }
    38→
    39→    logger.debug(`✅ [DVF Cache] Cache hit: ${key}`);
    40→    return entry.data as T;
    41→  }
    42→
    43→  delete(key: string): boolean {
    44→    const deleted = this.cache.delete(key);
    45→    if (deleted) {
    46→      logger.debug(`🗑️ [DVF Cache] Deleted key: ${key}`);
    47→    }
    48→    return deleted;
    49→  }
    50→
    51→  clear(): void {
    52→    const size = this.cache.size;
    53→    this.cache.clear();
    54→    logger.debug(`🧹 [DVF Cache] Cleared ${size} entries`);
    55→  }
    56→
    57→  size(): number {
    58→    return this.cache.size;
    59→  }
    60→
    61→  cleanup(): number {
    62→    const now = Date.now();
    63→    let removed = 0;
    64→
    65→    for (const [key, entry] of this.cache.entries()) {
    66→      if (now > entry.expiry) {
    67→        this.cache.delete(key);
    68→        removed++;
    69→      }
    70→    }
    71→
    72→    if (removed > 0) {
    73→      logger.debug(
    74→        `🧹 [DVF Cache] Cleanup: removed ${removed} expired entries`,
    75→      );
    76→    }
    77→
    78→    return removed;
    79→  }
    80→
    81→  generateKey(...parts: (string | number)[]): string {
    82→    return parts.map((part) => String(part)).join(":");
    83→  }
    84→}
