   367→        performanceScore
   368→      );
   369→      
   370→      return {
   371→        dpe,
   372→        analysisDate: new Date().toISOString(),
   373→        confidenceLevel: dpe.dataSource === "mock" ? "medium" : "high",
   374→        
   375→        // Coûts
   376→        estimatedAnnualCost: energyCost.annualAmount,
   377→        estimatedMonthlyCost: energyCost.monthlyAmount,
   378→        costComparisonToAverage: this.calculateCostComparison(dpe.energyConsumption.class),
   379→        
   380→        // Conformité réglementaire
   381→        rentalRestrictionRisk: rentalRisk,
   382→        renovationRequired: rentalRisk === "high" || rentalRisk === "critical",
   383→        renovationPriority,
   384→        estimatedRenovationCost: renovationCost,
   385→        
   386→        // Performance
   387→        performanceScore,
   388→        energyEfficiencyRating: efficiencyRating,
   389→        environmentalImpactRating: environmentalRating,
   390→        
   391→        // Recommandations
   392→        recommendations,
   393→        
   394→        // Données sources
   395→        dataSource: dpe.dataSource,
