   408→
   409→  /**
   410→   * Calcule la comparaison de coût par rapport à la moyenne
   411→   */
   412→  private calculateCostComparison(energyClass: EnergyClass): number {
   413→    // Valeurs moyennes nationales par classe (en €/an pour 100m²)
   414→    const averageCosts = {
   415→      A: 600,
   416→      B: 1000,
   417→      C: 1500,
   418→      D: 2100,
   419→      E: 2900,
   420→      F: 3800,
   421→      G: 4800,
   422→    };
   423→    
   424→    const currentCost = averageCosts[energyClass];
   425→    const nationalAverage = 2200; // Moyenne nationale actuelle
   426→    
   427→    return Math.round(((currentCost - nationalAverage) / nationalAverage) * 100);
   428→  }
   429→
   430→  /**
   431→   * Calcule la priorité de rénovation
   432→   */
   433→  private calculateRenovationPriority(
   434→    rentalRestrictionRisk: "low" | "medium" | "high" | "critical",
   435→    performanceScore: number
   436→  ): "low" | "medium" | "high" {
   437→    if (rentalRestrictionRisk === "critical" || rentalRestrictionRisk === "high") {
   438→      return "high";
   439→    }
   440→    
   441→    if (performanceScore < 30 || rentalRestrictionRisk === "medium") {
   442→      return "medium";
   443→    }
   444→    
   445→    return "low";
   446→  }
   447→
   448→  /**
   449→   * Calcule le niveau de confiance de l'analyse
   450→   */
   451→  private calculateConfidenceLevel(dpe: DPE): "low" | "medium" | "high" {
   452→    // Haute confiance si données récentes et complètes
   453→    if (dpe.dataSource === "api" && dpe.insulation && dpe.equipment) {
   454→      return "high";
   455→    }
   456→    
   457→    // Moyenne confiance si données partielles
   458→    if (dpe.dataSource === "api" || dpe.dataSource === "mock") {
   459→      return "medium";
   460→    }
   461→    
   462→    // Faible confiance pour les données estimées
   463→    return "low";
   464→  }
   465→
   466→  /**
   467→   * Génère une clé de cache
   468→   */
   469→  private getCacheKey(prefix: string, data: unknown): string {
   470→    const dataString = JSON.stringify(data);
   471→    return `${prefix}_${dataString}`;
   472→  }
   473→}
