     1→import { env } from "@/lib/env";
     2→
     3→export type TravelMode = "driving" | "walking" | "cycling";
     4→
     5→export type IsochroneRequest = {
     6→  coordinates: [number, number]; // [longitude, latitude]
     7→  contours: number[]; // Array of minutes (e.g., [5, 10, 15, 30])
     8→  mode: TravelMode;
     9→  excludeRoads?: ("motorway" | "toll" | "ferry" | "unpaved")[];
    10→  denoise?: boolean;
    11→  polygons?: boolean;
    12→};
    13→
    14→export type IsochroneContour = {
    15→  contour: number; // Duration in minutes
    16→  color: string;
    17→  opacity: number;
    18→  fillColor: string;
    19→  fillOpacity: number;
    20→};
    21→
    22→export type IsochroneFeature = {
    23→  type: "Feature";
    24→  properties: IsochroneContour;
    25→  geometry: {
    26→    type: "Polygon";
    27→    coordinates: [number, number][][]; // GeoJSON polygon coordinates
    28→  };
    29→};
    30→
    31→export type IsochroneResponse = {
    32→  type: "FeatureCollection";
    33→  features: IsochroneFeature[];
    34→};
    35→
    36→class IsochroneService {
    37→  private readonly baseUrl = "https://api.mapbox.com/isochrone/v1";
    38→  private readonly accessToken = env.NEXT_PUBLIC_MAPBOX_ACCESS_TOKEN ?? "";
    39→
    40→  async calculateIsochrones(
    41→    request: IsochroneRequest,
    42→  ): Promise<IsochroneResponse> {
    43→    const {
    44→      coordinates,
    45→      contours,
    46→      mode,
    47→      excludeRoads,
    48→      denoise = true,
    49→      polygons = true,
    50→    } = request;
    51→
    52→    const profile = this.mapTravelModeToProfile(mode);
    53→    const [lng, lat] = coordinates;
    54→
    55→    // Build query parameters
    56→    const params = new URLSearchParams({
    57→      contours_minutes: contours.join(","),
    58→      polygons: polygons.toString(),
    59→      denoise: denoise ? "1" : "0",
    60→      access_token: this.accessToken,
    61→    });
    62→
    63→    // Add optional exclude parameter
    64→    if (excludeRoads && excludeRoads.length > 0) {
    65→      params.append("exclude", excludeRoads.join(","));
    66→    }
    67→
    68→    // Add contour colors (using a predefined color scheme)
    69→    const colors = this.generateColors(contours.length);
    70→    params.append("contours_colors", colors.join(","));
    71→
    72→    const url = `${this.baseUrl}/${profile}/${lng},${lat}?${params.toString()}`;
    73→
    74→    try {
    75→      const response = await fetch(url);
    76→
    77→      if (!response.ok) {
    78→        throw new Error(
    79→          `Isochrone API error: ${response.status} ${response.statusText}`,
    80→        );
    81→      }
    82→
    83→      const data: IsochroneResponse = await response.json();
    84→      return data;
    85→    } catch (error) {
    86→      console.debug("Failed to calculate isochrones:", error);
    87→      throw new Error("Unable to calculate travel time zones");
    88→    }
    89→  }
    90→
    91→  private mapTravelModeToProfile(mode: TravelMode): string {
    92→    const profiles = {
    93→      driving: "mapbox/driving",
    94→      walking: "mapbox/walking",
    95→      cycling: "mapbox/cycling",
    96→    };
    97→    return profiles[mode];
    98→  }
    99→
   100→  private generateColors(count: number): string[] {
   101→    // Generate colors from light to dark for different contours
   102→    const baseColors = [
   103→      "6fce7f", // Light green for short distances
   104→      "4d9f3f", // Medium green
   105→      "2d5a1f", // Dark green
   106→      "1a3d0f", // Very dark green
   107→    ];
   108→
   109→    return baseColors.slice(0, count);
   110→  }
   111→
   112→  /* eslint-disable @typescript-eslint/member-ordering */
   113→  // Helper method to check if a point is inside an isochrone polygon
   114→  isPointInPolygon(
   115→    point: [number, number],
   116→    polygon: [number, number][][],
   117→  ): boolean {
   118→    const [lng, lat] = point;
   119→    const coordinates = polygon[0]; // First ring is the outer boundary
   120→
   121→    let inside = false;
   122→    for (
   123→      let i = 0, j = coordinates.length - 1;
   124→      i < coordinates.length;
   125→      j = i++
   126→    ) {
   127→      const [xi, yi] = coordinates[i];
   128→      const [xj, yj] = coordinates[j];
   129→
   130→      if (
   131→        yi > lat !== yj > lat &&
   132→        lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi
   133→      ) {
   134→        inside = !inside;
   135→      }
   136→    }
   137→    return inside;
   138→  }
   139→
   140→  // Filter properties that are within any of the isochrone contours
   141→  filterPropertiesInIsochrones<
   142→    T extends { id: string; coordinates: [number, number] },
   143→  >(properties: T[], isochrones: IsochroneResponse): T[] {
   144→    return properties.filter((property) => {
   145→      return isochrones.features.some((feature) => {
   146→        return this.isPointInPolygon(
   147→          property.coordinates,
   148→          feature.geometry.coordinates,
   149→        );
   150→      });
   151→    });
   152→  }
   153→
   154→  // Get the minimum travel time for a property (which contour it belongs to)
   155→  getPropertyTravelTime(
   156→    propertyCoords: [number, number],
   157→    isochrones: IsochroneResponse,
   158→  ): number | null {
   159→    const matchingContours: number[] = [];
   160→
   161→    for (const feature of isochrones.features) {
   162→      if (this.isPointInPolygon(propertyCoords, feature.geometry.coordinates)) {
   163→        matchingContours.push(feature.properties.contour);
   164→      }
   165→    }
   166→
   167→    // Return the smallest contour (shortest travel time)
   168→    return matchingContours.length > 0 ? Math.min(...matchingContours) : null;
   169→  }
   170→  /* eslint-enable @typescript-eslint/member-ordering */
   171→}
   172→
   173→export const isochroneService = new IsochroneService();
   174→

