    46→ * @param params[0] : payload
    47→ * @param params[1] : options
    48→ * @returns a promise of the email sent
    49→ */
    50→
    51→// If you use another mail adapter, you can replace the mailAdapter with your own
    52→const mailAdapter: MailAdapter = resendMailAdapter;
