    59→export const sendEmail = async (params: SendEmailParams) => {
    60→  if (env.NODE_ENV === "development") {
    61→    params.subject = `[DEV] ${params.subject}`;
    62→  }
    63→
    64→  // Avoid sending emails to playwright-test emails
    65→  if (
    66→    Array.isArray(params.to)
    67→      ? params.to.some((to) => to.startsWith("playwright-test-"))
    68→      : params.to.startsWith("playwright-test-")
    69→  ) {
    70→    logger.info("[sendEmail] Sending email to playwright-test", {
    71→      subject: params.subject,
    72→      to: params.to,
    73→    });
    74→
    75→    return {
    76→      error: null,
    77→      data: {
    78→        id: nanoid(),
    79→      },
    80→    };
    81→  }
    82→
    83→  let html = "";
    84→
    85→  if (typeof params.html === "string") {
    86→    html = params.html;
    87→  } else {
    88→    html = await pretty(await render(params.html));
    89→  }
    90→
    91→  const result = await mailAdapter.send({
    92→    ...params,
    93→    from: params.from ?? env.EMAIL_FROM,
    94→    html,
    95→  });
    96→
    97→  if (result.error) {
