     1→import { AUTH_PLANS } from "@/lib/auth/stripe/auth-plans";
     2→import { env } from "@/lib/env";
     3→import { logger } from "@/lib/logger";
     4→import { prisma } from "@/lib/prisma";
     5→import { stripe } from "@/lib/stripe";
     6→import { headers } from "next/headers";
     7→import type { NextRequest } from "next/server";
     8→import { NextResponse } from "next/server";
     9→import type Stripe from "stripe";
    10→export const maxDuration = 300;
    11→
    12→// Utility function to get plan from subscription metadata
    13→const getPlanFromSubscription = (subscription: Stripe.Subscription) => {
    14→  const planName = subscription.metadata.plan;
    15→  if (!planName) return null;
    16→
    17→  return AUTH_PLANS.find((p) => p.name === planName);
    18→};
    19→
    20→export const POST = async (req: NextRequest) => {
    21→  const headerList = await headers();
    22→  const body = await req.text();
    23→
    24→  const stripeSignature = headerList.get("stripe-signature");
    25→
    26→  let event: Stripe.Event | null = null;
    27→  try {
    28→    event = stripe.webhooks.constructEvent(
    29→      body,
    30→      stripeSignature ?? "",
    31→      env.STRIPE_WEBHOOK_SECRET ?? "",
    32→    );
    33→  } catch (err: unknown) {
    34→    logger.error("Stripe webhook signature verification failed:", err);
    35→    return NextResponse.json(
    36→      { error: "Invalid Stripe webhook signature", details: err },
    37→      { status: 400 },
    38→    );
    39→  }
    40→
    41→  try {
    42→    switch (event.type) {
    43→      case "checkout.session.completed":
    44→        await checkoutSessionCompleted(event.data.object, req);
    45→        break;
    46→      case "customer.subscription.updated":
    47→        await customerSubscriptionUpdated(event.data.object, req);
    48→        break;
    49→      case "customer.subscription.deleted":
    50→        await customerSubscriptionDeleted(event.data.object, req);
    51→        break;
    52→      default:
    53→        logger.error(`Unhandled event type: ${event.type}`);
    54→        break;
    55→    }
    56→  } catch (error) {
    57→    logger.error(`Error handling webhook event ${event.type}:`, error);
    58→    return NextResponse.json(
    59→      { error: "Webhook handler failed", eventType: event.type },
    60→      { status: 500 },
    61→    );
    62→  }
    63→
    64→  return NextResponse.json({
    65→    ok: true,
    66→  });
    67→};
    68→
    69→const checkoutSessionCompleted = async (
    70→  sessionData: Stripe.Checkout.Session,
    71→  req: NextRequest,
    72→) => {
    73→  const session = sessionData;
    74→
    75→  if (!session.customer || !session.subscription) {
    76→    logger.warn("Missing customer or subscription in checkout session");
    77→    return;
    78→  }
    79→
    80→  const customerId =
    81→    typeof session.customer === "string"
    82→      ? session.customer
    83→      : session.customer.id;
    84→  const subscriptionId =
    85→    typeof session.subscription === "string"
    86→      ? session.subscription
    87→      : session.subscription.id;
    88→
    89→  // Find organization by Stripe customer ID
    90→  const organization = await prisma.organization.findFirst({
    91→    where: { stripeCustomerId: customerId },
    92→    include: {
    93→      members: {
    94→        include: {
    95→          user: true,
    96→        },
    97→      },
    98→    },
    99→  });
   100→
   101→  if (!organization) {
   102→    logger.error(`Organization not found for customer ID: ${customerId}`);
   103→    return;
   104→  }
   105→
   106→  // Get the subscription from Stripe to get the price details
   107→  const stripeSubscription =
   108→    await stripe.subscriptions.retrieve(subscriptionId);
   109→  const priceId = stripeSubscription.items.data[0]?.price.id;
   110→
   111→  if (!priceId) {
   112→    logger.error(`No price ID found for subscription: ${subscriptionId}`);
   113→    return;
   114→  }
   115→
   116→  // Get plan from subscription metadata
   117→  const plan = getPlanFromSubscription(stripeSubscription);
   118→  if (!plan) {
   119→    logger.error(`Plan not found in subscription metadata: ${subscriptionId}`);
   120→    return;
   121→  }
   122→
   123→  // Create or update subscription
   124→  const existingSubscription = await prisma.subscription.findFirst({
   125→    where: { referenceId: organization.id },
   126→  });
   127→
   128→  let dbSubscription;
   129→  if (existingSubscription) {
   130→    dbSubscription = await prisma.subscription.update({
   131→      where: { id: existingSubscription.id },
   132→      data: {
   133→        plan: plan.name,
   134→        stripeCustomerId: customerId,
   135→        stripeSubscriptionId: subscriptionId,
   136→        status: stripeSubscription.status,
   137→        periodStart: new Date(
   138→          stripeSubscription.items.data[0].current_period_start * 1000,
   139→        ),
   140→        periodEnd: new Date(
   141→          stripeSubscription.items.data[0].current_period_end * 1000,
   142→        ),
   143→        cancelAtPeriodEnd: stripeSubscription.cancel_at_period_end,
   144→        seats: stripeSubscription.items.data[0]?.quantity ?? 1,
   145→      },
   146→    });
   147→  } else {
   148→    dbSubscription = await prisma.subscription.create({
   149→      data: {
   150→        id: `sub_${Date.now()}`,
   151→        plan: plan.name,
   152→        referenceId: organization.id,
   153→        stripeCustomerId: customerId,
   154→        stripeSubscriptionId: subscriptionId,
   155→        status: stripeSubscription.status,
   156→        periodStart: new Date(
   157→          stripeSubscription.items.data[0].current_period_start * 1000,
   158→        ),
   159→        periodEnd: new Date(
   160→          stripeSubscription.items.data[0].current_period_end * 1000,
   161→        ),
   162→        cancelAtPeriodEnd: stripeSubscription.cancel_at_period_end,
   163→        seats: stripeSubscription.items.data[0]?.quantity ?? 1,
   164→      },
   165→    });
   166→  }
   167→
   168→  // Call onTrialStart if this is a trial subscription
   169→  if (
   170→    stripeSubscription.status === "trialing" &&
   171→    plan.freeTrial?.onTrialStart
   172→  ) {
   173→    await plan.freeTrial.onTrialStart(dbSubscription, {
   174→      req,
   175→      organizationId: organization.id,
   176→      stripeCustomerId: customerId,
   177→      subscriptionId: subscriptionId,
   178→    });
   179→  }
   180→
   181→  logger.info(
   182→    `Subscription created/updated for organization: ${organization.id}, plan: ${plan.name}`,
   183→  );
   184→};
   185→
   186→const customerSubscriptionUpdated = async (
   187→  subscriptionData: Stripe.Subscription,
   188→  req: NextRequest,
   189→) => {
   190→  const subscription = subscriptionData;
   191→
   192→  logger.info("Processing customer.subscription.updated:", subscription.id);
   193→
   194→  // Find the subscription in our database
   195→  const dbSubscription = await prisma.subscription.findFirst({
   196→    where: { stripeSubscriptionId: subscription.id },
   197→  });
   198→
   199→  if (!dbSubscription) {
   200→    logger.error(`Subscription not found in database: ${subscription.id}`);
   201→    return;
   202→  }
   203→
   204→  // Get plan from subscription metadata
   205→  const plan = getPlanFromSubscription(subscription);
   206→  const planName = plan?.name ?? dbSubscription.plan; // Keep current plan as fallback
   207→
   208→  // Update subscription details
   209→  const updatedSubscription = await prisma.subscription.update({
   210→    where: { id: dbSubscription.id },
   211→    data: {
   212→      plan: planName,
   213→      status: subscription.status,
   214→      periodStart: new Date(
   215→        subscription.items.data[0].current_period_start * 1000,
   216→      ),
   217→      periodEnd: new Date(subscription.items.data[0].current_period_end * 1000),
   218→      cancelAtPeriodEnd: subscription.cancel_at_period_end,
   219→      seats: subscription.items.data[0]?.quantity ?? dbSubscription.seats ?? 1,
   220→    },
   221→  });
   222→
   223→  // Handle trial transitions
   224→  if (plan?.freeTrial) {
   225→    // Trial ended and became active
   226→    if (
   227→      subscription.status === "active" &&
   228→      dbSubscription.status === "trialing" &&
   229→      plan.freeTrial.onTrialEnd
   230→    ) {
   231→      await plan.freeTrial.onTrialEnd(
   232→        { subscription: updatedSubscription },
   233→        {
   234→          req,
   235→          organizationId: updatedSubscription.referenceId,
   236→          stripeCustomerId: subscription.customer as string,
   237→          subscriptionId: subscription.id,
   238→        },
   239→      );
   240→    }
   241→
   242→    // Trial expired
   243→    if (
   244→      subscription.status === "incomplete_expired" &&
   245→      dbSubscription.status === "trialing" &&
   246→      plan.freeTrial.onTrialExpired
   247→    ) {
   248→      await plan.freeTrial.onTrialExpired(updatedSubscription, {
   249→        req,
   250→        organizationId: updatedSubscription.referenceId,
   251→        stripeCustomerId: subscription.customer as string,
   252→        subscriptionId: subscription.id,
   253→      });
   254→    }
   255→  }
   256→
   257→  logger.info(
   258→    `Subscription updated: ${subscription.id}, status: ${subscription.status}, plan: ${planName}`,
   259→  );
   260→};
   261→
   262→const customerSubscriptionDeleted = async (
   263→  subscriptionData: Stripe.Subscription,
   264→  req: NextRequest,
   265→) => {
   266→  const subscription = subscriptionData;
   267→
   268→  logger.info("Processing customer.subscription.deleted:", subscription.id);
   269→
   270→  // Find and update the subscription status
   271→  const dbSubscription = await prisma.subscription.findFirst({
   272→    where: { stripeSubscriptionId: subscription.id },
   273→  });
   274→
   275→  if (!dbSubscription) {
   276→    logger.error(`Subscription not found in database: ${subscription.id}`);
   277→    return;
   278→  }
   279→
   280→  // Get plan from subscription metadata
   281→  const plan = getPlanFromSubscription(subscription);
   282→
   283→  // Update subscription to canceled/free plan
   284→  const updatedSubscription = await prisma.subscription.update({
   285→    where: { id: dbSubscription.id },
   286→    data: {
   287→      plan: "free",
   288→      status: "canceled",
   289→      cancelAtPeriodEnd: false,
   290→      periodEnd: new Date(), // Set to current time since it's canceled
   291→    },
   292→  });
   293→
   294→  // Call onSubscriptionCanceled if available
   295→  if (plan?.onSubscriptionCanceled) {
   296→    await plan.onSubscriptionCanceled(updatedSubscription, {
   297→      req,
   298→      organizationId: updatedSubscription.referenceId,
   299→      stripeCustomerId: subscription.customer as string,
   300→      subscriptionId: subscription.id,
   301→    });
   302→  }
   303→
   304→  logger.info(
   305→    `Subscription canceled and reverted to free plan: ${subscription.id}`,
   306→  );
   307→};
