     9→// Prix moyens de l'énergie en EUR/kWh (2024)
    10→const ENERGY_PRICES = {
    11→  electricity: 0.25,      // Prix moyen de l'électricité
    12→  gas: 0.08,              // Prix moyen du gaz naturel
    13→  fuel_oil: 0.10,         // Prix moyen du fioul
    14→  wood: 0.06,             // Prix moyen du bois
    15→  network: 0.09,          // Prix moyen du chauffage urbain
    16→  other: 0.15,            // Prix par défaut pour autres énergies
    17→} as const;
    18→
    19→// Classes de consommation réglementaires (en kWh_ep/m².an)
    20→const ENERGY_CLASS_THRESHOLDS = {
    21→  A: 50,
    22→  B: 90,
    23→  C: 150,
    24→  D: 230,
    25→  E: 330,
    26→  F: 450,
    27→  G: Infinity,
    28→} as const;
    29→
    30→// Classes d'émission GES réglementaires (en kgCO2/m².an)
    31→const GES_CLASS_THRESHOLDS = {
    32→  A: 5,
    33→  B: 10,
    34→  C: 20,
    35→  D: 35,
    36→  E: 55,
    37→  F: 80,
    38→  G: Infinity,
    39→} as const;
    40→
    41→/**
    42→ * Calcule la classe de consommation d'énergie
    43→ */
    44→export function calculateEnergyClass(consumption: number): EnergyClass {
    45→  if (consumption <= ENERGY_CLASS_THRESHOLDS.A) return "A";
    46→  if (consumption <= ENERGY_CLASS_THRESHOLDS.B) return "B";
    47→  if (consumption <= ENERGY_CLASS_THRESHOLDS.C) return "C";
    48→  if (consumption <= ENERGY_CLASS_THRESHOLDS.D) return "D";
    49→  if (consumption <= ENERGY_CLASS_THRESHOLDS.E) return "E";
    50→  if (consumption <= ENERGY_CLASS_THRESHOLDS.F) return "F";
    51→  return "G";
    52→}
    53→
    54→/**
    55→ * Calcule la classe d'émission de GES
    56→ */
    57→export function calculateGesClass(emission: number): GesClass {
    58→  if (emission <= GES_CLASS_THRESHOLDS.A) return "A";
    59→  if (emission <= GES_CLASS_THRESHOLDS.B) return "B";
    60→  if (emission <= GES_CLASS_THRESHOLDS.C) return "C";
    61→  if (emission <= GES_CLASS_THRESHOLDS.D) return "D";
    62→  if (emission <= GES_CLASS_THRESHOLDS.E) return "E";
    63→  if (emission <= GES_CLASS_THRESHOLDS.F) return "F";
    64→  return "G";
    65→}
    66→
    67→/**
    68→ * Calcule le coût énergétique annuel estimé
    69→ */
    70→export function calculateEnergyCost(
    71→  consumption: number, 
    72→  energyType: keyof typeof ENERGY_PRICES,
    73→  surface: number
    74→): {
    75→  annualAmount: number;
    76→  monthlyAmount: number;
    77→  currency: string;
    78→  energyPrice: number;
    79→} {
    80→  const pricePerKwh = ENERGY_PRICES[energyType];
    81→  const annualCost = consumption * surface * pricePerKwh;
    82→  
    83→  return {
    84→    annualAmount: Math.round(annualCost),
    85→    monthlyAmount: Math.round(annualCost / 12),
    86→    currency: "EUR",
    87→    energyPrice: pricePerKwh,
    88→  };
    89→}
    90→
    91→/**
    92→ * Évalue le risque de restriction de location (classes F et G)
    93→ */
    94→export function assessRentalRestrictionRisk(energyClass: EnergyClass, gesClass: GesClass): "low" | "medium" | "high" | "critical" {
    95→  // Classes F et G sont interdites à la location dans certaines zones
    96→  if (energyClass === "G" || gesClass === "G") return "critical";
    97→  if (energyClass === "F" || gesClass === "F") return "high";
    98→  if (energyClass === "E" || gesClass === "E") return "medium";
    99→  return "low";
   100→}
