   102→/**
   103→ * Génère des recommandations de rénovation
   104→ */
   105→export function generateRenovationRecommendations(dpe: DPE): {
   106→  category: string;
   107→  description: string;
   108→  estimatedCost?: number;
   109→  energySaving?: number;
   110→  paybackPeriod?: number;
   111→  priority: "low" | "medium" | "high";
   112→}[] {
   113→  const recommendations: {
   114→    category: string;
   115→    description: string;
   116→    estimatedCost?: number;
   117→    energySaving?: number;
   118→    paybackPeriod?: number;
   119→    priority: "low" | "medium" | "high";
   120→  }[] = [];
   121→
   122→  const { energyConsumption, insulation } = dpe;
   123→
   124→  // Isolation des murs
   125→  if (insulation?.wallInsulation === "poor" || energyConsumption.value > 200) {
   126→    recommendations.push({
   127→      category: "Isolation",
   128→      description: "Isolation des murs extérieurs",
   129→      estimatedCost: dpe.surface * 80, // ~80€/m²
   130→      energySaving: energyConsumption.value * 0.25, // ~25% d'économie
   131→      paybackPeriod: 15,
   132→      priority: energyConsumption.class === "G" || energyConsumption.class === "F" ? "high" : "medium",
   133→    });
   134→  }
   135→
   136→  // Double vitrage
   137→  if (!insulation?.hasDoubleGlazing) {
   138→    recommendations.push({
   139→      category: "Menuiseries",
   140→      description: "Remplacement des fenêtres par du double vitrage",
   141→      estimatedCost: dpe.surface * 200, // ~200€/m²
   142→      energySaving: energyConsumption.value * 0.15, // ~15% d'économie
   143→      paybackPeriod: 20,
   144→      priority: "medium",
   145→    });
   146→  }
   147→
   148→  // Isolation des combles
   149→  if (insulation?.roofInsulation === "poor" || energyConsumption.value > 150) {
   150→    recommendations.push({
   151→      category: "Isolation",
   152→      description: "Isolation des combles",
   153→      estimatedCost: dpe.surface * 40, // ~40€/m²
   154→      energySaving: energyConsumption.value * 0.20, // ~20% d'économie
   155→      paybackPeriod: 8,
   156→      priority: "high",
   157→    });
   158→  }
   159→
   160→  // Chauffage performant
   161→  if (energyConsumption.class === "F" || energyConsumption.class === "G") {
   162→    recommendations.push({
   163→      category: "Chauffage",
   164→      description: "Installation d'une chaudière à haute performance",
   165→      estimatedCost: 10000,
   166→      energySaving: energyConsumption.value * 0.30, // ~30% d'économie
   167→      paybackPeriod: 12,
   168→      priority: "high",
   169→    });
   170→  }
   171→
   172→  return recommendations;
   173→}
   174→
   175→/**
   176→ * Calcule un score de performance global (0-100)
   177→ */
   178→export function calculatePerformanceScore(dpe: DPE): number {
   179→  const energyScore = getEnergyClassScore(dpe.energyConsumption.class);
   180→  const gesScore = getGesClassScore(dpe.gesEmission.class);
   181→  
   182→  // Pondération : 60% énergie, 40% GES
   183→  const weightedScore = (energyScore * 0.6) + (gesScore * 0.4);
   184→  
   185→  return Math.round(weightedScore);
   186→}
   187→
   188→/**
   189→ * Convertit la classe d'énergie en score numérique
   190→ */
   191→function getEnergyClassScore(energyClass: EnergyClass): number {
   192→  const scores = { A: 100, B: 85, C: 70, D: 55, E: 40, F: 25, G: 10 };
   193→  return scores[energyClass];
   194→}
   195→
   196→/**
   197→ * Convertit la classe GES en score numérique
   198→ */
   199→function getGesClassScore(gesClass: GesClass): number {
   200→  const scores = { A: 100, B: 85, C: 70, D: 55, E: 40, F: 25, G: 10 };
   201→  return scores[gesClass];
   202→}
   203→
   204→/**
   205→ * Évalue la performance énergétique
   206→ */
   207→export function assessEnergyEfficiencyRating(score: number): "excellent" | "good" | "average" | "poor" | "very_poor" {
   208→  if (score >= 85) return "excellent";
   209→  if (score >= 70) return "good";
   210→  if (score >= 50) return "average";
   211→  if (score >= 30) return "poor";
   212→  return "very_poor";
   213→}
   214→
   215→/**
   216→ * Évalue l'impact environnemental
   217→ */
   218→export function assessEnvironmentalImpactRating(gesClass: GesClass): "excellent" | "good" | "average" | "poor" | "very_poor" {
   219→  if (gesClass === "A" || gesClass === "B") return "excellent";
   220→  if (gesClass === "C") return "good";
   221→  if (gesClass === "D") return "average";
   222→  if (gesClass === "E") return "poor";
   223→  // gesClass is "F" or "G"
   224→  return "very_poor";
   225→}
   226→
   227→/**
   228→ * Calcule le coût de rénovation estimé
   229→ */
   230→export function estimateRenovationCost(recommendations: {
   231→  estimatedCost?: number;
   232→  priority: "low" | "medium" | "high";
   233→}[]): number {
   234→  // Ne prendre en compte que les recommandations high et medium priority
   235→  const relevantRecommendations = recommendations.filter(
   236→    rec => rec.priority === "high" || rec.priority === "medium"
   237→  );
   238→  
   239→  return relevantRecommendations.reduce((total, rec) => {
   240→    return total + (rec.estimatedCost ?? 0);
   241→  }, 0);
   242→}
   243→
   244→/**
   245→ * Valide les données DPE
   246→ */
   247→export function validateDPEData(data: Record<string, unknown>): DPE {
   248→  try {
   249→    // Validation manuelle des champs requis pour éviter les problèmes d'import
   250→    if (!data.id || !data.address || !data.postalCode || !data.city) {
   251→      throw new Error("Champs requis manquants: id, address, postalCode, city");
   252→    }
   253→    
   254→    if (!data.propertyType || !data.surface || !data.yearBuilt) {
   255→      throw new Error("Champs requis manquants: propertyType, surface, yearBuilt");
   256→    }
   257→    
   258→    if (!data.energyConsumption || !data.gesEmission) {
   259→      throw new Error("Champs de performance énergétique manquants");
   260→    }
   261→    
   262→    if (typeof data.surface !== 'number' || data.surface <= 0) {
   263→      throw new Error("Surface doit être un nombre positif");
   264→    }
   265→    
   266→    // Validation des classes d'énergie
   267→    const validEnergyClasses = ["A", "B", "C", "D", "E", "F", "G"];
   268→    const energyClass = (data.energyConsumption as { class?: string }).class;
   269→    if (!energyClass || !validEnergyClasses.includes(energyClass)) {
   270→      throw new Error("Classe de consommation énergétique invalide");
   271→    }
   272→
   273→    const gesClass = (data.gesEmission as { class?: string }).class;
   274→    if (!gesClass || !validEnergyClasses.includes(gesClass)) {
   275→      throw new Error("Classe d'émission GES invalide");
   276→    }
   277→
   278→    // Retourner les données validées
   279→    return data as DPE;
   280→  } catch (error) {
   281→    if (error instanceof Error) {
   282→      throw new DPEValidationError(
   283→        `Validation des données DPE échouée: ${error.message}`,
   284→        [error]
   285→      );
   286→    }
   287→    throw new DPEValidationError("Validation des données DPE échouée");
   288→  }
   289→}
   290→
   291→/**
   292→ * Normalise les données DPE brutes provenant de différentes sources
   293→ */
   294→export function normalizeDPERawData(rawData: Record<string, unknown> | unknown): Partial<DPE> {
   295→  const data = rawData as Record<string, unknown>;
   296→  return {
   297→    id: (data.id ?? data.numero_dpe ?? `dpe_${Date.now()}`) as string,
   298→    address: (data.address ?? data.adresse) as string,
   299→    postalCode: (data.postalCode ?? data.code_postal) as string,
   300→    city: (data.city ?? data.ville) as string,
   301→    coordinates: (data.coordinates ?? data.coordonnees_geographiques) as [number, number] | undefined,
   302→
   303→    propertyType: (data.propertyType ?? data.type_batiment ?? "apartment") as "apartment" | "house" | "mixed_use" | "other",
   304→    surface: (data.surface ?? data.surface_habitable) as number,
   305→    yearBuilt: (data.yearBuilt ?? data.annee_construction) as number,
   306→    livingArea: (data.livingArea ?? data.surface_habitable) as number | undefined,
   307→
   308→    energyConsumption: (data.energyConsumption ?? data.consommation_energie ?? {
   309→      value: (data.consommation_energie_value ?? data.consomme_energie ?? 0) as number,
   310→      unit: "kWh_ep/m².an" as const,
   311→      maxAuthorized: (data.maxAuthorized ?? 450) as number,
   312→      class: (data.classe_consommation_energie ?? data.classe_energy ?? "G") as EnergyClass,
   313→    }) as { value: number; unit: "kWh_ep/m².an"; maxAuthorized: number; class: EnergyClass },
   314→
   315→    gesEmission: (data.gesEmission ?? data.emission_ges ?? {
   316→      value: (data.emission_ges_value ?? data.estimation_ges ?? 0) as number,
   317→      unit: "kgCO2/m².an" as const,
   318→      maxAuthorized: (data.maxAuthorizedGes ?? 80) as number,
   319→      class: (data.classe_estimation_ges ?? data.classe_ges ?? "G") as GesClass,
   320→    }) as { value: number; unit: "kgCO2/m².an"; maxAuthorized: number; class: GesClass },
   321→
   322→    mainEnergyType: (data.mainEnergyType ?? data.type_energie_principale ?? "electricity") as "electricity" | "gas" | "fuel_oil" | "wood" | "coal" | "network" | "other",
   323→
   324→    dpeDate: (data.dpeDate ?? data.date_dpe) as string,
   325→    dpeValidity: (data.dpeValidity ?? data.date_validite_dpe) as string,
   326→    dataSource: (data.dataSource ?? "unknown") as string,
   327→    lastUpdated: new Date().toISOString(),
   328→  };
   329→}

