   128→      console.debug(`Failed to enrich favorite ${favoriteId} with DPE data:`, error);
   129→
   130→      // Même en cas d'erreur, on essaie de générer des données mockées
   131→      try {
   132→        const mockAnalysis = await this.generateMockDPEAnalysis(favoriteId);
   133→        const prisma = new PrismaClient();
   134→        await prisma.favorite.update({
   135→          where: { id: favoriteId },
   136→          data: {
   137→            dpeClass: mockAnalysis.dpe.energyConsumption.class,
   138→            gesClass: mockAnalysis.dpe.gesEmission.class,
   139→            energyConsumption: mockAnalysis.dpe.energyConsumption.value,
   140→            gesEmission: mockAnalysis.dpe.gesEmission.value,
   141→            annualEnergyCost: mockAnalysis.estimatedAnnualCost,
   142→            rentalRestrictionRisk: mockAnalysis.rentalRestrictionRisk,
   143→            renovationRequired: mockAnalysis.renovationRequired,
   144→            estimatedRenovationCost: mockAnalysis.estimatedRenovationCost,
   145→            energyAnalysis: mockAnalysis,
   146→            confidenceScore: 50, // Score moyen pour les données mockées
   147→          },
   148→        });
   149→
   150→        return {
   151→          favoriteId,
   152→          success: true,
   153→          dpeData: mockAnalysis,
   154→        };
   155→      // eslint-disable-next-line @typescript-eslint/no-unused-vars
